func:
// ==================================================
// 0. CONTROLLO DI COERENZA (SANITY CHECK) & FAIL-SAFE
// ==================================================
// --- CONTROLLO DI COERENZA E STATO PERSISTENTE ---
let variabiliCritiche = [
    { nome: "user_min_run_time", defaultVal: 15 },
    { nome: "user_min_off_time", defaultVal: 20 },
    { nome: "user_deficit_tolerance_time", defaultVal: 40 },
    { nome: "user_vmc_max_notte", defaultVal: 2 },
    { nome: "user_target_humidex_estate", defaultVal: 29.0 },
    { nome: "user_emergency_humidex_away", defaultVal: 33.0 },
    { nome: "user_humidex_comfort_hysteresis", defaultVal: 2.5 },
    { nome: "user_night_dry_humidex_margin", defaultVal: 0.5 },
    { nome: "grace_mode_solar", defaultVal: false }
];

let mancanti = [];

variabiliCritiche.forEach(v => {
    let val = global.get(v.nome, "file");
    if (val === undefined) {
        mancanti.push(v.nome);
        global.set(v.nome, v.defaultVal, "file");
    }
});

let msgHealth = {
    topic: "casa/clima/system_health/stat"
};

if (mancanti.length > 0) {
    node.warn("STATO SISTEMA INCONSISTENTE: Parametri globali mancanti su file -> " + mancanti.join(", "));
    msgHealth.payload = {
        stato: "INCONSISTENTE",
        motivo: "Mancanza di parametri globali persistenti, ripristinati i default",
        elementi_mancanti: mancanti,
        timestamp: Date.now()
    };
} else {
    msgHealth.payload = {
        stato: "NORMALE",
        timestamp: Date.now()
    };
}

// ==================================================
// 1. MEMORIZZAZIONE DEI DATI IN INGRESSO
// ==================================================
if (msg.topic === "system/boot") {
    // Boot sync
}
else if (msg.topic === "TeslaPowerwall/solar_instant_power") {
    flow.set("produzione", parseFloat(msg.payload), "file");
}
else if (msg.topic === "TeslaPowerwall/load_instant_power") {
    flow.set("consumo", parseFloat(msg.payload), "file");
}
else if (msg.topic === "TeslaPowerwall/site_instant_power") {
    flow.set("grid_power", parseFloat(msg.payload), "file");
}
else if (msg.topic === "TeslaPowerwall/battery_instant_power") {
    flow.set("battery_power", parseFloat(msg.payload), "file");
}
else if (msg.topic === "emon/planetary/altitude") {
    flow.set("sun_altitude", parseFloat(msg.payload), "file");
}
else if (msg.topic === "TeslaPowerwall/SOE") {
    let rawSoc = parseFloat(msg.payload);
    let lastValidSoc = flow.get("powerwall_soc", "file");

    if (lastValidSoc === undefined) {
        flow.set("powerwall_soc", rawSoc, "file");
    } else {
        let delta = Math.abs(rawSoc - lastValidSoc);
        if (delta <= 3.0) {
            flow.set("powerwall_soc", rawSoc, "file");
            flow.set("soc_glitch_count", 0, "file"); 
        } else {
            let glitchCount = flow.get("soc_glitch_count", "file") || 0;
            glitchCount++;
            if (glitchCount >= 5) {
                flow.set("powerwall_soc", rawSoc, "file");
                flow.set("soc_glitch_count", 0, "file");
            } else {
                flow.set("soc_glitch_count", glitchCount, "file");
            }
        }
    }
}
else if (msg.topic === "emon/emonth5/temperature_calibrated") {
    flow.set("temperatura", parseFloat(msg.payload),"file");
}
else if (msg.topic === "zara/domotics/LivingHumidex") {
    flow.set("humidex_giorno", parseFloat(msg.payload), "file");
}
else if (msg.topic === "zara/domotics/BedroomHumidex") {
    flow.set("humidex_notte", parseFloat(msg.payload), "file");
}
else if (msg.topic === "zigbee2mqtt/Sonoff AirGuard TH esterno cucina") {
    flow.set("temp_esterno", parseFloat(msg.payload.temperature));
    flow.set("umidita_esterno", parseFloat(msg.payload.humidity));
}
else if (msg.topic === "emon/cameraMatrimoniale/temperature") {
    flow.set("temp_cameraMatrimoniale", parseFloat(msg.payload));
}
else if (msg.topic === "emon/AC/emeter_power") {
    flow.set("ac_power", Math.abs(parseFloat(msg.payload)), "file"); 
}

let meseAttuale = new Date().getMonth();
let MODALITA_STAGIONE = (meseAttuale >= 4 && meseAttuale <= 8) ? "ESTATE" : "INVERNO";

let tempEsterna = flow.get("temp_esterno");
let umiditaEsterna = flow.get("umidita_esterno");

if (tempEsterna === undefined || umiditaEsterna === undefined) {
    tempEsterna = (MODALITA_STAGIONE === "ESTATE") ? 24 : 8;
    umiditaEsterna = 60;
}

let aEst = 17.27;
let bEst = 237.7;
let alphaEst = ((aEst * tempEsterna) / (bEst + tempEsterna)) + Math.log(umiditaEsterna / 100);
let dewPointEst = (bEst * alphaEst) / (aEst - alphaEst);
let eEst = 6.11 * Math.exp(5417.7530 * ((1 / 273.15) - (1 / (273.15 + dewPointEst))));
let humidexEsterno = parseFloat((tempEsterna + (5 / 9) * (eEst - 10)).toFixed(1));

let adesso = Date.now();
let statoAttuale = flow.get("condizionatore_stato", "file") || "OFF";

let ultimoAvvio = global.get("ultimo_avvio", "file") || (adesso - 40 * 60 * 1000);
let ultimoSpegnimento = global.get("ultimo_spegnimento", "file") || (adesso - 40 * 60 * 1000);

const MIN_RUN_MINUTI = parseFloat(global.get("user_min_run_time", "file")) || 15;
const MIN_OFF_MINUTI = parseFloat(global.get("user_min_off_time", "file")) || 15;
const DEFICIT_TOLERANCE_MINUTI = parseFloat(global.get("user_deficit_tolerance_time", "file")) || 10; 
const VMC_MAX_NOTTE = parseInt(global.get("user_vmc_max_notte", "file")) || 2;
const TARGET_HUMIDEX_ESTATE = parseFloat(global.get("user_target_humidex_estate", "file")) || 29;
const EMERGENCY_HUMIDEX_AWAY = parseFloat(global.get("user_emergency_humidex_away", "file")) || 33.0;

let humidexComfortHysteresis =
    parseFloat(global.get("user_humidex_comfort_hysteresis", "file"));

if (!Number.isFinite(humidexComfortHysteresis)) {
    humidexComfortHysteresis = 2.5;
}

let nightDryHumidexMargin =
    parseFloat(global.get("user_night_dry_humidex_margin", "file"));

if (!Number.isFinite(nightDryHumidexMargin)) {
    nightDryHumidexMargin = 0.5;
}

const MIN_RUN_TIME = MIN_RUN_MINUTI * 60 * 1000;
const MIN_OFF_TIME = MIN_OFF_MINUTI * 60 * 1000;
const DEFICIT_TOLERANCE_TIME = DEFICIT_TOLERANCE_MINUTI * 60 * 1000; 

let tempoPassatoDallAccensione = adesso - ultimoAvvio;
let tempoPassatoDalloSpegnimento = adesso - ultimoSpegnimento;

let minMancantiSpegnimento = tempoPassatoDallAccensione < MIN_RUN_TIME ? Math.ceil((MIN_RUN_TIME - tempoPassatoDallAccensione) / 60000) : 0;
let minMancantiAccensione = tempoPassatoDalloSpegnimento < MIN_OFF_TIME ? Math.ceil((MIN_OFF_TIME - tempoPassatoDalloSpegnimento) / 60000) : 0;
let tempoMancanteMinuti = (statoAttuale === "OFF") ? minMancantiAccensione : minMancantiSpegnimento;

// ==================================================
// 2. RECUPERO DERIVAZIONI ENERGETICHE E ASTRONOMICHE
// ==================================================
let prod = flow.get("produzione", "file") || 0;
let cons = flow.get("consumo", "file") || 0;
let soc = (flow.get("powerwall_soc", "file") !== undefined) ? flow.get("powerwall_soc", "file") : 0;
let temp = flow.get("temperatura", "file") || 19;
let hGiorno = flow.get("humidex_giorno", "file") || 0;
let hNotte = flow.get("humidex_notte", "file") || 0;
let temp_cameraMatrimoniale = flow.get("temp_cameraMatrimoniale") || 0;
let acPower = flow.get("ac_power", "file") || 0;

let gridPowerRaw = flow.get("grid_power", "file") || 0;
let batteryPowerRaw = flow.get("battery_power", "file") || 0;
let sunAltitude = flow.get("sun_altitude", "file"); 
if (sunAltitude === undefined) sunAltitude = 90; 

let gridImportW = Math.max(gridPowerRaw, 0);
let gridExportW = Math.max(-gridPowerRaw, 0);
let batteryDischargeW = Math.max(batteryPowerRaw, 0);
let batteryChargeW = Math.max(-batteryPowerRaw, 0);

let vmc_portata = [0, 50, 130, 160, 300];
let oraAttuale = new Date().getHours();
let surplus = prod - cons;

let kwhDomani = flow.get("previsione_kwh_domani") || 12;
let dataDomani = flow.get("previsione_data_domani") || "N/A";
let tutteMedie = flow.get("tutte_medie_storiche", "file") || global.get("tutte_medie_storiche", "file") || { ESTATE: { GIORNO: 600, NOTTE: 400 }, INVERNO: { GIORNO: 800, NOTTE: 500 } };

let dataOraFormattata = new Intl.DateTimeFormat('it-IT', {
    timeZone: 'Europe/Rome', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', second: '2-digit', hour12: false
}).format(new Date(adesso));

let esNotteFascia = (oraAttuale >= 22 || oraAttuale < 8);
let humidex = esNotteFascia ? hNotte : hGiorno;
if (humidex === 0) humidex = (hGiorno !== 0) ? hGiorno : hNotte;

const CAPACITA_BATTERIA_KWH = 13.5;
let consumoDiurnoStimatoKwh = (tutteMedie[MODALITA_STAGIONE]["GIORNO"] * 12) / 1000;
if (isNaN(consumoDiurnoStimatoKwh) || consumoDiurnoStimatoKwh < 3) consumoDiurnoStimatoKwh = 7.5;

let energiaDisponibilePerBatteriaKwh = (kwhDomani - consumoDiurnoStimatoKwh) * 0.95;
if (energiaDisponibilePerBatteriaKwh < 0) energiaDisponibilePerBatteriaKwh = 0;

let socStimatoMattino = soc - 15;
if (socStimatoMattino < 0) socStimatoMattino = 0;
if (socStimatoMattino > 100) socStimatoMattino = 100; 

let capacitaVuotaKwh = CAPACITA_BATTERIA_KWH * (1 - (socStimatoMattino / 100));
let kwhDestinatiAllaBatteria = 0;
let percentualeRicaricaPrevista = 0;

if (energiaDisponibilePerBatteriaKwh >= capacitaVuotaKwh) {
    kwhDestinatiAllaBatteria = capacitaVuotaKwh;
    percentualeRicaricaPrevista = 100;
} else {
    kwhDestinatiAllaBatteria = energiaDisponibilePerBatteriaKwh;
    let ricaricaAggiuntivaPercentuale = (energiaDisponibilePerBatteriaKwh / CAPACITA_BATTERIA_KWH) * 100;
    percentualeRicaricaPrevista = Math.round(socStimatoMattino + ricaricaAggiuntivaPercentuale);
}

if (percentualeRicaricaPrevista > 100) percentualeRicaricaPrevista = 100;
if (percentualeRicaricaPrevista < 0) percentualeRicaricaPrevista = 0;

let comandoIR = null;
// ACTIVE.4C.2G.1
// Richiesta pre-start PR causale.
// Rimane null salvo candidatura reale OFF -> NIGHT_DRY con PR ON.
let msgPrPrestart = null;
let sogliaAttivazioneLogica = 0;
let socMinimoLogico = 0;
let consumoStoricoAttuale = tutteMedie[MODALITA_STAGIONE][esNotteFascia ? "NOTTE" : "GIORNO"];

// --- Inizializzazione Variabili per Log e UI ---
let bloccoSpegnimentoEmergenza = false; 
let energiaDisponibileKwh = 0;
let consumoNotteStimatoKwh = 0;
let cuscinettoSicurezzaKwh = 0;
let cuscinettoMinimoRichiesto = 0;

// Parametri comfort AC esposti anche alla UI Android
let ampiezzaIsteresi = humidexComfortHysteresis;
let sogliaSpegnimentoComfort = 0;
let nightDryHumidexThreshold = 0;

// Causa che ha determinato una transizione AC nel ciclo corrente.
// Solo diagnostica: non partecipa alla logica di controllo.
let causaTransizioneAc = null;

// ==================================================
// 3. MASTER SWITCH E LOGICA INTEGRATA
// ==================================================
let aiAbilitata = flow.get("AI_climate_enabling", "file");
if (aiAbilitata === undefined) {
    aiAbilitata = true;
    flow.set("AI_climate_enabling", true, "file");
}
let systemWasDisabled = flow.get("system_was_disabled") || false;

let velocitaVmc = 1;
let motivoVmc = "STANDBY_MINIMO";
let motivoAc = "ANALISI_IN_CORSO";

if (!aiAbilitata) {
    if (!systemWasDisabled) {
        comandoIR = "OFF"; 
        statoAttuale = "OFF";
        flow.set("condizionatore_stato", "OFF", "file");
        flow.set("system_was_disabled", true);
        global.set("ultimo_spegnimento", adesso, "file");
    } else {
        statoAttuale = "OFF";
    }
    velocitaVmc = 1;
    motivoVmc = "SISTEMA_DISABILITATO";
    motivoAc = "SISTEMA_DISABILITATO_DA_UTENTE";
    tempoMancanteMinuti = 0;

} else {
    if (systemWasDisabled) {
        flow.set("system_was_disabled", false);
    }

    let bypassRoutine = false;

    if (statoAttuale !== "OFF" && acPower >= 10) {
        flow.set("tentativi_riavvio_ac", 0);
    }

    if (statoAttuale === "OFF" && acPower > 30 && (adesso - ultimoSpegnimento > 3 * 60 * 1000)) {
        comandoIR = "OFF";
        global.set("ultimo_spegnimento", adesso, "file"); 
        ultimoSpegnimento = adesso;                      
        motivoAc = "WATCHDOG_FALSO_OFF";
        bypassRoutine = true; 
    }
    else if (statoAttuale !== "OFF" && statoAttuale !== "STANDBY_INVERTER" && acPower < 10 && (adesso - ultimoAvvio > 6 * 60 * 1000)) {
        let tentativi = flow.get("tentativi_riavvio_ac") || 0;

        if (tentativi < 3) {
            tentativi++;
            flow.set("tentativi_riavvio_ac", tentativi);

            statoAttuale = "OFF";
            flow.set("condizionatore_stato", "OFF", "file");
            global.set("ultimo_spegnimento", adesso - MIN_OFF_TIME - 1000, "file");
            tempoMancanteMinuti = 0;
            minMancantiAccensione = 0;
            motivoAc = "WATCHDOG_TENTATIVO_RIAVVIO_" + tentativi;
        } else {
            aiAbilitata = false;
            flow.set("AI_climate_enabling", false, "file");
            flow.set("tentativi_riavvio_ac", 0);

            comandoIR = "OFF"; 
            statoAttuale = "OFF";
            flow.set("condizionatore_stato", "OFF", "file");
            global.set("ultimo_spegnimento", adesso, "file");
            motivoAc = "WATCHDOG_SOSPENSIONE_SISTEMA_GUASTO";
            bypassRoutine = true;
        }
    }

    if (!bypassRoutine && aiAbilitata) {
        if (MODALITA_STAGIONE === "INVERNO") {
            sogliaAttivazioneLogica = esNotteFascia ? 17.0 : 19.0;
            socMinimoLogico = esNotteFascia ? (kwhDomani >= 22 && consumoStoricoAttuale < 700 ? 25 : (kwhDomani <= 8 || consumoStoricoAttuale > 1000 ? 60 : 40)) : 0;
            motivoAc = "LOGICA_INVERNALE_ATTIVA";

            if (statoAttuale === "OFF") {
                if (!esNotteFascia && surplus > (consumoStoricoAttuale * 0.8) && temp < 19.0) {
                    if (minMancantiAccensione === 0) {
                        statoAttuale = "HEAT_DIURNO"; flow.set("condizionatore_stato", "HEAT_DIURNO", "file"); global.set("ultimo_avvio", adesso, "file"); comandoIR = "eco19heat";
                    }
                }
                else if (esNotteFascia && temp < 17.0 && soc > socMinimoLogico) {
                    if (minMancantiAccensione === 0) {
                        statoAttuale = "HEAT_SICUREZZA_NOTTE"; flow.set("condizionatore_stato", "HEAT_SICUREZZA_NOTTE", "file"); global.set("ultimo_avvio", adesso, "file"); comandoIR = "eco17heat";
                    }
                }
            } else {
                let richiediSpegnimentoInverno = false;
                if (statoAttuale === "HEAT_DIURNO" && (esNotteFascia || surplus < -150 || temp >= 19.5)) richiediSpegnimentoInverno = true;
                if (statoAttuale === "HEAT_SICUREZZA_NOTTE" && (!esNotteFascia || temp >= 17.5 || soc <= socMinimoLogico)) richiediSpegnimentoInverno = true;

                if (richiediSpegnimentoInverno && minMancantiSpegnimento === 0) {
                    statoAttuale = "OFF"; flow.set("condizionatore_stato", "OFF", "file"); global.set("ultimo_spegnimento", adesso, "file"); comandoIR = "OFF";
                }
            }
        }
        else if (MODALITA_STAGIONE === "ESTATE") {
            sogliaAttivazioneLogica = TARGET_HUMIDEX_ESTATE;

            let esSeraFasciaDinamica = (oraAttuale >= 15 && oraAttuale < 22 && sunAltitude <= 20);

            if (esNotteFascia) {
                socMinimoLogico = (kwhDomani >= 28 && consumoStoricoAttuale < 450 ? 20 : (kwhDomani <= 12 ? 55 : 35));
            } else if (esSeraFasciaDinamica) {

                energiaDisponibileKwh = (soc / 100) * CAPACITA_BATTERIA_KWH;
                let oreAllAlba = (8 + 24 - oraAttuale) % 24; 
                consumoNotteStimatoKwh = (tutteMedie["ESTATE"]["NOTTE"] * oreAllAlba) / 1000;
                cuscinettoSicurezzaKwh = energiaDisponibileKwh - consumoNotteStimatoKwh;

                cuscinettoMinimoRichiesto = 1.0; 
                if (percentualeRicaricaPrevista < 95) {
                    let deficitRicaricaPct = 95 - percentualeRicaricaPrevista;
                    cuscinettoMinimoRichiesto += (deficitRicaricaPct * 0.05);
                }

                if (batteryDischargeW > 2500) {
                    socMinimoLogico = 100; 
                    bloccoSpegnimentoEmergenza = true;
                    motivoAc = `PEAK_SHAVING_ATTIVO (Scarica: ${batteryDischargeW}W)`;
                } 
                else if (cuscinettoSicurezzaKwh < cuscinettoMinimoRichiesto) {
                    socMinimoLogico = 100; 
                    bloccoSpegnimentoEmergenza = true;
                    motivoAc = `SOPRAVVIVENZA_NOTTE_ATTIVA (Cusc: ${cuscinettoSicurezzaKwh.toFixed(1)} < Riq: ${cuscinettoMinimoRichiesto.toFixed(1)}kWh)`;
                } 
                else {
                    socMinimoLogico = 45; 
                }
            } else {
                socMinimoLogico = (global.get("grace_mode_solar", "file") === true) ? 85 : 35; 
            }

            let gracePeriodStr = global.get("grace_period_time_range", "file") || "8-12";
            let graceParts = gracePeriodStr.split("-");
            let graceStart = parseInt(graceParts[0]) || 8;
            let graceEnd = parseInt(graceParts[1]) || 16;

            let isPeriodoDiGrazia = (oraAttuale >= graceStart && oraAttuale < graceEnd);
            let usaSoloSolare = global.get("grace_mode_solar", "file") === true; 

            if (isPeriodoDiGrazia) {
                if (!usaSoloSolare) {
                    sogliaAttivazioneLogica = EMERGENCY_HUMIDEX_AWAY;
                }
            }

            nightDryHumidexThreshold = sogliaAttivazioneLogica + nightDryHumidexMargin;

            // Valore effettivo della soglia comfort, disponibile anche per datiAndroid.
            sogliaSpegnimentoComfort = sogliaAttivazioneLogica - ampiezzaIsteresi;

            let surplusVirtuale = (statoAttuale === "OFF") ? (surplus - 700) : surplus;
            let solareForteDaOff = (!esNotteFascia && percentualeRicaricaPrevista >= 90 && surplusVirtuale > 500);
            let solareForteAttivo = (!esNotteFascia && percentualeRicaricaPrevista >= 90 && surplus > 300);

            if (statoAttuale === "OFF") {
                let transizionePermessa = false;

                if (minMancantiAccensione > 0) {
                    motivoAc = "BLOCCO_TIMER_ANTICICLO_OFF";
                } else if (bloccoSpegnimentoEmergenza) {
                    // Mantiene il divieto e il motivo impostato dai controlli di sicurezza
                } else if (esNotteFascia) {
                    let ultimoSpegnimentoNotte = flow.get("ultimo_spegnimento_notte", "file") || 0;
                    let tempoMinimoPausaNotte = 45 * 60 * 1000;

                    if (soc <= socMinimoLogico) {
                        motivoAc = "BLOCCO_NOTTE_BATTERIA_BASSA";
                    } else if (humidex < nightDryHumidexThreshold) {
                        motivoAc = "COMFORT_NOTTURNO_RAGGIUNTO";
                    } else if ((adesso - ultimoSpegnimentoNotte) < tempoMinimoPausaNotte) {
                        motivoAc = "BLOCCO_NOTTE_PAUSA_45M";
                    } else {
                        motivoAc = "PRONTO_ACCENSIONE_NIGHT_DRY";
                    }
                } else {
/*
                    if (isPeriodoDiGrazia && usaSoloSolare && surplus < 1000 && !solareForteDaOff) {
                        motivoAc = "BLOCCO_GRAZIA_VINCOLO_SOLARE";
*/
                    if (temp < 24.0) {
                        motivoAc = "BLOCCO_DIURNO_TEMPERATURA_BASSA";
                    } else if (humidex < sogliaAttivazioneLogica) {
                        // Diagnostica: la richiesta comfort non è ancora presente.
                        // L'AC resta OFF indipendentemente dalla disponibilità di surplus.
                        motivoAc = "ATTESA_SOGLIA_HUMIDEX";
                    } else if (isPeriodoDiGrazia && usaSoloSolare && surplus < 1000 && !solareForteDaOff) {
                        motivoAc = "BLOCCO_GRAZIA_VINCOLO_SOLARE";
                    } else if (soc < socMinimoLogico && humidex < EMERGENCY_HUMIDEX_AWAY && !solareForteDaOff) {
                        motivoAc = "BLOCCO_DIURNO_BATTERIA";
                    } else if (surplusVirtuale <= 150 && humidex < EMERGENCY_HUMIDEX_AWAY && !solareForteDaOff) {
                        // La richiesta comfort è presente, ma manca la condizione energetica.
                        motivoAc = "ATTESA_SURPLUS_SOLARE";
                    } else {
                        motivoAc = (solareForteDaOff && soc < socMinimoLogico) ? "PRONTO_ACCENSIONE_OVERRIDE_SOLARE" : "PRONTO_ACCENSIONE_COOLING";
                    }
                }

                if (bloccoSpegnimentoEmergenza) {
                    transizionePermessa = false; 
                } else if (esSeraFasciaDinamica) {
                    if (soc >= socMinimoLogico && humidex >= sogliaAttivazioneLogica) transizionePermessa = true;
                } else if (esNotteFascia) {
                    if (soc > 75 && humidex >= (sogliaAttivazioneLogica + 1.0)) transizionePermessa = true;
                } else {
                    if ((soc >= socMinimoLogico || solareForteDaOff) && surplusVirtuale > 150) transizionePermessa = true;
                    if (humidex >= EMERGENCY_HUMIDEX_AWAY) transizionePermessa = true;
                    if (isPeriodoDiGrazia && usaSoloSolare) {
                        if (surplus < 1000 && !solareForteDaOff) transizionePermessa = false;
                    }
                }

                if (!esNotteFascia && 
                    transizionePermessa && 
                    humidex >= sogliaAttivazioneLogica &&
                    temp >= 24.0) {
                    if (minMancantiAccensione === 0) {
                        statoAttuale = "COOLING_ON"; flow.set("condizionatore_stato", "COOLING_ON", "file"); global.set("ultimo_avvio", adesso, "file");
                        if (temp >= 26) comandoIR = "23"; else if (temp >= 25) comandoIR = "24"; else if (temp >= 24) comandoIR = "23"; else if (temp >= 23) comandoIR = "22"; else comandoIR = "26";
                        motivoAc = "ESECUZIONE_ACCENSIONE_DIURNA";
                    }
                } else if (esNotteFascia && soc > socMinimoLogico) {
                    let ultimoSpegnimentoNotte = flow.get("ultimo_spegnimento_notte", "file") || 0;
                    let tempoMinimoPausaNotte = 45 * 60 * 1000;

                    if (humidex >= nightDryHumidexThreshold) {

                        if (
                            (adesso - ultimoSpegnimentoNotte) >= tempoMinimoPausaNotte &&
                            minMancantiAccensione === 0
                        ) {
                            // ==================================================
                            // PR-ACTIVE.2B.5
                            // PRESELEZIONE COMANDO CANDIDATO NIGHT_DRY
                            //
                            // Calcolo puro:
