                                            prReason = "SNAPSHOT_INVALID";
                                        }

                                        else {

                                            // Preferiamo il timestamp della vera
                                            // Final SHADOW Decision.
                                            // Non permettiamo che un adapter
                                            // "ringiovanisca" una decisione vecchia.
                                            const sourceTs =
                                                snap.source &&
                                                Number(
                                                    snap.source
                                                        .final_decision_timestamp_ms
                                                );

                                            const snapshotTs =
                                                Number(snap.timestamp_ms);

                                            const decisionTs =
                                                Number.isFinite(sourceTs)
