                            }


                            // ==================================================
                            // DENY
                            //
                            // Nessuna mutazione:
                            // - statoAttuale resta OFF
                            // - condizionatore_stato non viene scritto
                            // - ultimo_avvio non viene scritto
                            // - comandoIR non viene prodotto
                            // ==================================================

                            else {

                                motivoAc =
                                    "BLOCCO_PR_" + prReason;
