                                    candidateCommandIR;

                                motivoAc =
                                    "ESECUZIONE_ACCENSIONE_NOTTURNA";
                            }


                            // --------------------------------------------------
                            // PR ON -> HANDSHAKE PRE-COMMIT
                            // --------------------------------------------------

                            else if (
                                prGate &&
